import type { DirectoryCompany, DirectoryStats } from '@/lib/directory-types'
import { isRetailEntityType } from '@/lib/directory-types'
import { classifyEntityType } from '@/lib/entity-classifier'
import { brokers } from './brokers'

/**
 * Convert existing Broker to DirectoryCompany format
 */
function convertBrokerToDirectoryCompany(broker: typeof brokers[0]): DirectoryCompany {
  return {
    id: broker.id,
    slug: broker.slug,
    name: broker.name,
    legalName: broker.legalName,
    logoUrl: broker.logoUrl,
    websiteUrl: broker.websiteUrl,
    affiliateUrl: broker.affiliateUrl,
    category: 'forex-broker',
    // T41: mechanical entity type seeding — no manual guessing.
    entityType: classifyEntityType(broker.name, broker.shortDescription),
    verificationStatus: broker.verificationStatus ?? 'unverified',
    dataQualityStage: 'reviewed',
    shortDescription: broker.shortDescription,
    longDescription: broker.longDescription,
    foundedYear: broker.foundedYear,
    headquarters: broker.headquarters,
    country: broker.headquarters?.split(', ').pop(),
    rating: broker.rating,
    ratingLabel: broker.ratingLabel,
    rank: broker.rank,
    // P0-262: broker.regulators may be string[] or object[]{authority,country,licenseNumber}
    // (e.g. go-markets, infinox). Normalise to string[] so every downstream consumer
    // (join, slice, render) receives plain strings and never crashes with [object Object].
    regulators: broker.regulators?.map((r) =>
      typeof r === 'string' ? r : (r as { authority: string }).authority
    ),
    regulationSummary: broker.regulators
      ?.map((r) => (typeof r === 'string' ? r : (r as { authority: string }).authority))
      .join(', '),
    platforms: broker.platforms,
    instruments: broker.instruments,
    currencyPairs: broker.currencyPairs,
    minDeposit: broker.minDeposit,
    spreadsFrom: broker.spreadsFrom,
    commissions: broker.commissions,
    maxLeverageRetail: broker.maxLeverageRetail,
    maxLeverageProfessional: broker.maxLeverageProfessional,
    depositMethods: broker.depositMethods,
    withdrawalMethods: broker.withdrawalMethods,
    withdrawalTime: broker.withdrawalTime,
    accountTypes: broker.accountTypes,
    hasBonus: broker.bonuses && broker.bonuses.length > 0,
    bonusSummary: broker.bonuses?.[0]?.title,
    pros: broker.pros,
    cons: broker.cons,
    scores: broker.scores,
    seo: broker.seo,
    isFeatured: broker.isFeatured,
    isSponsored: broker.isSponsored,
    sourceUrls: broker.sourceUrls,
    lastVerifiedAt: broker.lastVerifiedAt,
    lastUpdatedAt: broker.lastVerifiedAt,
    bestFor: broker.bestFor,
    badges: broker.badges,
    mobileApps: broker.mobileApps,
    countriesServed: broker.countriesServed,
    restrictedCountries: broker.restrictedCountries,
    inactivityFee: broker.inactivityFee,
    bonuses: broker.bonuses,
  }
}

