/**
 * Processes all additionalCompanies:
 * 1. Brands with dataQualityStage 'reviewed' or 'enriched' keep their verification status
 * 2. Brands with dataQualityStage 'basic' are marked 'unverified'
 * 3. Assigns sequential scores (1.0 → 4.5, step 0.1) to basic-stage brands based
 *    on insertion order (oldest = 1.0, newest = 4.5)
 *
 * Top 5 brokers from brokers.ts are NOT processed here — they keep their
 * existing 'sponsored'/'verified' status and scores untouched.
 */
function processAdditionalCompanies(companies: DirectoryCompany[]): DirectoryCompany[] {
  // Collect all 'basic' brands in order for score assignment
  const basicBrands = companies.filter(c => c.dataQualityStage === 'basic' && !c.scores)
  const total = basicBrands.length

  // Build a score lookup by id (1.0 oldest → 4.5 newest)
  const scoreMap = new Map<string, number>()
  basicBrands.forEach((brand, i) => {
    const fraction = total <= 1 ? 0 : i / (total - 1)
    const rawScore = 1.0 + fraction * 3.5
    scoreMap.set(brand.id, Math.round(rawScore * 10) / 10)
  })

  return companies.map(company => {
    const overall = scoreMap.get(company.id)
    const hasScore = overall !== undefined

    const ratingLabel =
      !hasScore ? company.ratingLabel :
      overall! >= 4.5 ? 'Excellent' :
      overall! >= 4.0 ? 'Very Good' :
      overall! >= 3.0 ? 'Good' :
      overall! >= 2.0 ? 'Fair' : 'Basic'

    // Only mark 'basic' stage brands as unverified; reviewed/enriched keep their status
    const verificationStatus = company.dataQualityStage === 'basic' 
      ? 'unverified' as const 
      : company.verificationStatus

    return {
      ...company,
      verificationStatus,
      ...(hasScore && {
        rating: overall,
        ratingLabel,
        scores: { overall: overall! },
      }),
    }
  })
}

/**
 * Convert all existing brokers to directory format and combine with additional companies.
 * Top 5 brokers from brokers.ts retain their 'sponsored'/'verified' status and scores.
 * All additionalCompanies are marked 'unverified' with sequential scores (1.0–4.5).
 */
const _rawDirectoryCompanies: DirectoryCompany[] = [
  ...brokers.map(convertBrokerToDirectoryCompany),
  ...processAdditionalCompanies(additionalCompanies),
]

/**
 * T41: Apply entity-type classification to every record that doesn't already
 * have an explicit entityType. This is the single point that seeds all 1,800+
 * entries without touching each record individually.
 */
export const directoryCompanies: DirectoryCompany[] = _rawDirectoryCompanies.map(c => ({
  ...c,
  entityType: c.entityType ?? classifyEntityType(c.name, c.shortDescription),
}))

/**
 * T41: Retail-only view — only forex_broker, cfd_broker, and prop_firm.
 * Used by /brokers rankings, pagination, and A-Z. Non-retail entity types
 * (exchange, hedge_fund, bank_desk, clearing, investment_bank,
 * prediction_market) are excluded.
 */
// Fixed pinned order for the top brands on /brokers.
// Positions are locked; everything else follows by tier then rating.
// Sponsored first (saxo-bank, capital-com), then verified by prominence.
const PINNED_DIRECTORY_SLUGS = [
  'saxo-bank',
  'capital-com',
  'forex-com',
  'dukascopy',
  'swissquote',
  'eightcap',
  'ninjatrader',
  'tastyfx',
  'moneta-markets',
  'vantage',
  'fusion-markets',
]

function verificationTier(c: DirectoryCompany): number {
  if (c.isSponsored || c.verificationStatus === 'sponsored') return 0
  if (c.verificationStatus === 'verified' || c.verificationStatus === 'claimed') return 1
  return 2
}

function compareStableIdentity(a: DirectoryCompany, b: DirectoryCompany): number {
  if (a.slug !== b.slug) return a.slug < b.slug ? -1 : 1
  if (a.id === b.id) return 0
  return a.id < b.id ? -1 : 1
}

export const rankedBrokers: DirectoryCompany[] = (() => {
  const retail = directoryCompanies.filter(c => isRetailEntityType(c.entityType))
  const bySlug = new Map(retail.map(c => [c.slug, c]))

  // Build pinned list — only include slugs that exist in the directory
  const pinned: DirectoryCompany[] = []
  for (const slug of PINNED_DIRECTORY_SLUGS) {
    const c = bySlug.get(slug)
    if (c) pinned.push(c)
  }

  const pinnedIds = new Set(pinned.map(c => c.id))

  // Remaining entries sorted by tier then rating
  const rest = retail
    .filter(c => !pinnedIds.has(c.id))
    .sort((a, b) => {
      const tierDiff = verificationTier(a) - verificationTier(b)
      if (tierDiff !== 0) return tierDiff
      const ratingDiff = (b.rating ?? 0) - (a.rating ?? 0)
      if (ratingDiff !== 0) return ratingDiff
      return compareStableIdentity(a, b)
    })

  return [...pinned, ...rest]
})()

/**
 * Get all unique countries from directory
 */
export function getDirectoryCountries(): string[] {
  const countries = new Set<string>()
  directoryCompanies.forEach(company => {
    if (company.country) countries.add(company.country)
    if (company.headquarters) {
      const country = company.headquarters.split(', ').pop()
      if (country) countries.add(country)
    }
  })
  return Array.from(countries).sort()
}

/**
 * Get all unique regulators from directory
 */
export function getDirectoryRegulators(): string[] {
  const regulators = new Set<string>()
  directoryCompanies.forEach(company => {
    company.regulators?.forEach(reg => regulators.add(reg))
  })
  return Array.from(regulators).sort()
}

/**
 * Get all unique platforms from directory
 */
export function getDirectoryPlatforms(): string[] {
  const platforms = new Set<string>()
  directoryCompanies.forEach(company => {
    company.platforms?.forEach(p => platforms.add(p))
  })
  return Array.from(platforms).sort()
}

/**
 * Directory statistics
 */
export function getDirectoryStats(): DirectoryStats {
  const brokerCount = directoryCompanies.filter(c => c.category !== 'prop-firm').length
  const propFirmCount = directoryCompanies.filter(c => c.category === 'prop-firm').length
  const countries = getDirectoryCountries()
  const regulators = getDirectoryRegulators()
  
  return {
    totalBrokers: brokerCount,
    totalPropFirms: propFirmCount,
    countriesCovered: countries.length,
    regulatorsCovered: regulators.length,
    dataPoints: 100,
    lastUpdated: new Date().toISOString().split('T')[0],
  }
}

/**
 * Get company by slug
 */
export function getCompanyBySlug(slug: string): DirectoryCompany | undefined {
  // Case-insensitive lookup so that /Plus500, /PLUS500 and /plus500 all resolve
  // to the same broker. The canonical slug stored in the data is always lowercase.
  const normalised = slug.toLowerCase()
  return directoryCompanies.find(c => c.slug === normalised)
}

/**
 * Search and filter directory companies
 */
export function searchDirectory(
  query?: string,
  filters?: {
    category?: string
    country?: string
    regulator?: string
    platform?: string
    verificationStatus?: string
    hasBonus?: boolean
  },
  sortBy: string = 'rating',
  sortOrder: 'asc' | 'desc' = 'desc',
  sourceCompanies: DirectoryCompany[] = directoryCompanies
  ): DirectoryCompany[] {
  let results = [...sourceCompanies]

  
  // Search by query
  if (query && query.trim()) {
    const searchTerm = query.toLowerCase().trim()
    results = results.filter(company =>
      company.name.toLowerCase().includes(searchTerm) ||
      company.shortDescription?.toLowerCase().includes(searchTerm) ||
      company.country?.toLowerCase().includes(searchTerm) ||
      company.regulators?.some(r => typeof r === 'string' && r.toLowerCase().includes(searchTerm)) ||
      company.platforms?.some(p => typeof p === 'string' && p.toLowerCase().includes(searchTerm))
    )
  }
  
  // Filter by category
  if (filters?.category && filters.category !== 'all') {
    results = results.filter(c => c.category === filters.category)
  }
  
  // Filter by country
  if (filters?.country && filters.country !== 'all') {
    const country = filters.country
    results = results.filter(c =>
      c.country === country ||
      c.headquarters?.includes(country)
    )
  }
  
  // Filter by regulator
  if (filters?.regulator && filters.regulator !== 'all') {
    results = results.filter(c => 
      c.regulators?.some(r => r.includes(filters.regulator!))
    )
  }
  
  // Filter by platform
  if (filters?.platform && filters.platform !== 'all') {
    results = results.filter(c => 
      c.platforms?.includes(filters.platform!)
    )
  }
  
  // Filter by verification status
  if (filters?.verificationStatus && filters.verificationStatus !== 'all') {
    results = results.filter(c => c.verificationStatus === filters.verificationStatus)
  }
  
  // Filter by bonus availability
  if (filters?.hasBonus !== undefined) {
    results = results.filter(c => c.hasBonus === filters.hasBonus)
  }
  
  // Sort results
  results.sort((a, b) => {
    let comparison = 0
    
    switch (sortBy) {
      case 'rating':
        comparison = (b.rating || 0) - (a.rating || 0)
        break
      case 'featured':
        // Sponsored first, then featured, then by rating
        if (a.isSponsored !== b.isSponsored) return a.isSponsored ? -1 : 1
        if (a.isFeatured !== b.isFeatured) return a.isFeatured ? -1 : 1
        comparison = (b.rating || 0) - (a.rating || 0)
        break
      case 'name':
        comparison = a.name.localeCompare(b.name)
        break
      case 'newest':
        comparison = (b.lastUpdatedAt || '').localeCompare(a.lastUpdatedAt || '')
        break
      case 'min-deposit':
        const aDeposit = parseFloat(a.minDeposit?.replace(/[^0-9.]/g, '') || '999999')
        const bDeposit = parseFloat(b.minDeposit?.replace(/[^0-9.]/g, '') || '999999')
        comparison = aDeposit - bDeposit
        break
      default:
        comparison = (b.rating || 0) - (a.rating || 0)
    }
    
    const directionalComparison = sortOrder === 'asc' ? -comparison : comparison
    if (directionalComparison !== 0) return directionalComparison
    return compareStableIdentity(a, b)
  })
  
  return results
}
